code.cpp:
class Solution {
public:
    int findMaxK(vector<int>& nums) {
        bool present[2001] = {false};
        for (int x : nums) {
            present[x + 1000] = true;
        }
        for (int k = 1000; k >= 1; --k) {
            if (present[k + 1000] && present[1000 - k]) {
                return k;
            }
        }
        return -1;
    }
};
